def hardware_restore(relative):
    v=Q.load(HERE/'quota_origin.json');row=next(r for r in v['witnesses'] if r['current_relative']==relative)
    raw=Q.read_small(REPO/relative);text=raw.decode()
    for edit in reversed(row['edits']):
        need(edit['new'] in text,'DECLARED_HARDWARE_DELTA_MISSING:'+relative);text=text.replace(edit['new'],edit['old'])
    old=base64.b64decode(row['original_base64'],validate=True);ref=row['original_reference']
    need(len(old)==ref['bytes'] and hashlib.sha256(old).hexdigest()==ref['sha256'] and text.encode()==old,
        'WHOLE_SOURCE_HARDWARE_INVERSE_BYTES:'+relative)
    if relative.endswith('.py'):
        need(ast.dump(ast.parse(text),include_attributes=False)==ast.dump(ast.parse(old),include_attributes=False),
            'WHOLE_SOURCE_HARDWARE_INVERSE_AST:'+relative)
    return text

